 let r=await q("SELECT id FROM users WHERE email='admin@purposepay.test'");if(!r.rows[0]){const uid=id('USR');await q('INSERT INTO users(id,email,password_hash,role,first_name,last_name,kyc_status) VALUES($1,$2,$3,$4,$5,$6,$7)',[uid,'admin@purposepay.test',await bcrypt.hash('Admin12345!',12),'ADMIN','PurposePay','Admin','VERIFIED'])}
 r=await q("SELECT id FROM users WHERE email='demo@purposepay.test'");if(r.rows[0])return;
 const uid=id('USR'),mid=id('MER'),muid=id('USR'),cuid=id('USR'),sid=id('SCH'),pid=id('PRJ'),vid=id('VCH'),tx=id('TXN');
 await q('INSERT INTO users(id,email,password_hash,role,first_name,last_name,phone,kyc_status) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[uid,'demo@purposepay.test',await bcrypt.hash('Demo12345!',12),'CUSTOMER','Demo','Customer','+233200000000','VERIFIED']);
 await q('INSERT INTO users(id,email,password_hash,role,first_name,last_name,kyc_status) VALUES($1,$2,$3,$4,$5,$6,$7)',[muid,'merchant@purposepay.test',await bcrypt.hash('Merchant12345!',12),'MERCHANT','ABC','Merchant','VERIFIED']);
 await q('INSERT INTO merchants(id,user_id,name,status,categories_json,settlement_status) VALUES($1,$2,$3,$4,$5,$6)',[mid,muid,'ABC Building Materials','APPROVED',JSON.stringify(['Cement','Blocks','Steel','Roofing']),'PENDING']);
 await q('INSERT INTO users(id,email,password_hash,role,first_name,last_name,phone,kyc_status) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[cuid,'contractor@purposepay.test',await bcrypt.hash('Contractor12345!',12),'CONTRACTOR','Kwame','Mensah','+233200000001','VERIFIED']);
 await q('INSERT INTO schools(id,name,status) VALUES($1,$2,$3)',[sid,'Accra International School','APPROVED']);
